CREATE EXTENSION IF NOT EXISTS vector; CREATE EXTENSION IF NOT EXISTS pgcrypto; CREATE TABLE IF NOT EXISTS catalog_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,title text NOT NULL,source_type text NOT NULL DEFAULT 'manual',content text NOT NULL,status text NOT NULL DEFAULT 'processing' CHECK(status IN('processing','indexed','failed')),chunk_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS catalog_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,document_id uuid NOT NULL REFERENCES catalog_documents(id) ON DELETE CASCADE,chunk_index integer NOT NULL,source_title text NOT NULL,content text NOT NULL,embedding vector(768) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(document_id,chunk_index)); CREATE INDEX IF NOT EXISTS catalog_chunks_workspace_idx ON catalog_chunks(workspace_id); CREATE INDEX IF NOT EXISTS catalog_chunks_embedding_idx ON catalog_chunks USING hnsw(embedding vector_cosine_ops); CREATE TABLE IF NOT EXISTS catalog_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,sku text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',unit text NOT NULL DEFAULT 'unit',price_amount numeric(14,2),price_currency char(3),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,sku)); CREATE INDEX IF NOT EXISTS catalog_items_search_idx ON catalog_items(workspace_id,is_active); CREATE TABLE IF NOT EXISTS inventory(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,catalog_item_id uuid NOT NULL REFERENCES catalog_items(id) ON DELETE CASCADE,available_quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK(available_quantity>=0),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,catalog_item_id)); CREATE TABLE IF NOT EXISTS conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,title text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS conversation_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN('user','assistant')),content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS conversation_messages_history_idx ON conversation_messages(workspace_id,conversation_id,created_at DESC); CREATE TABLE IF NOT EXISTS analyzed_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,original_message text NOT NULL,extracted_data jsonb NOT NULL,decision text NOT NULL,decision_payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS analyzed_requests_workspace_idx ON analyzed_requests(workspace_id,created_at DESC);